using System.Text;
using System.Text.Json;

namespace Albera.Setup;

/// <summary>Test pins: the SHA-256 of the synthetic gh.exe and trusted root that <see cref="Scenario"/> writes. The real ones are generated by scripts/publish-windows-setup.mjs.</summary>
internal static class PinnedTools
{
    public static string GhSha256 { get; set; } = FileSystemChecks.Sha256(Scenario.GhBytes);
    public static string TrustedRootSha256 { get; set; } = FileSystemChecks.Sha256(Scenario.RootBytes);
    /// <summary>The run id of the build that made this setup (generated as a constant in the real file; 0 = a local compile check, bounds nothing).</summary>
    public static ulong BuildRunId { get; set; }
}

/// <summary>Stands in for gh.exe and the installer: records every call, answers from the delegates.</summary>
internal sealed class FakeRunner : IProcessRunner
{
    public readonly List<ProcessSpec> Calls = [];
    public Func<ProcessSpec, ProcessResult> Gh { get; set; } = _ => throw new InvalidOperationException("gh was not expected");
    public Func<ProcessSpec, ProcessResult> Engine { get; set; } = _ => throw new InvalidOperationException("the installer was not expected");
    public IEnumerable<ProcessSpec> GhCalls => Calls.Where(IsGh);
    public IEnumerable<ProcessSpec> EngineCalls => Calls.Where(c => !IsGh(c));

    public ProcessResult Run(ProcessSpec spec)
    {
        Calls.Add(spec);
        return IsGh(spec) ? Gh(spec) : Engine(spec);
    }

    private static bool IsGh(ProcessSpec spec) => spec.FileName.EndsWith("gh.exe", StringComparison.OrdinalIgnoreCase);
}

/// <summary>One attestation as the fake gh prints it: the commit and run the certificate names.</summary>
internal sealed record Attested(ulong Run, string Commit);

/// <summary>
/// A synthetic update folder in a temp directory (every byte made up here; there is no real attestation in it) plus the dependencies of the flow, with gh and the installer faked.
/// The file list, the publish folder layout and build-hashes.json follow <see cref="SetupLayout"/>, so the flow runs exactly the code path of a real update.
/// </summary>
internal sealed class Scenario : IDisposable
{
    public static readonly byte[] GhBytes = "synthetic gh.exe for the unit tests\n"u8.ToArray();
    public static readonly byte[] RootBytes = "{\"synthetic\":\"trusted root for the unit tests\"}\n"u8.ToArray();
    public const string DefaultCommit = "0123456789abcdef0123456789abcdef01234567";
    public const ulong DefaultRun = 1234567;

    public readonly string Root = Path.Combine(Path.GetTempPath(), "albera-setup-unit-" + Guid.NewGuid().ToString("N"));
    public readonly FakeRunner Runner = new();
    public readonly StringWriter Out = new();
    public readonly Dictionary<string, string> RelativeBySha = [];
    public string Update => Path.Combine(Root, "update");
    public string SetupDirectory => Path.Combine(Root, "installed", "bin", "setup");
    public string WorkRoot => Path.Combine(Root, "setup-work");
    /// <summary>Where this scenario's install record would be (the real one is C:\ProgramData\Albera\install-manifest.json). No file exists until a check writes one.</summary>
    public string InstallRecordPath => Path.Combine(Root, "ProgramData", "Albera", "install-manifest.json");
    public string TreeHash { get; private set; } = "";
    public bool Elevated { get; set; } = true;
    public Func<string, IReadOnlyList<string>> AdminProblems { get; set; } = _ => [];
    /// <summary>Stands in for FileSystemChecks.CreateAdministratorOnlyDirectory (owning something as Administrators needs an elevated token).</summary>
    public Action<string> CreateWorkDirectory { get; set; } = path => Directory.CreateDirectory(path);
    public string? InstalledDirectory { get; set; }
    /// <summary>The attestations the fake gh reports per attested file (relative path). Default: one, DefaultRun / DefaultCommit.</summary>
    public Func<string, IReadOnlyList<Attested>> Attestations { get; set; } = _ => [new Attested(DefaultRun, DefaultCommit)];
    public Action<string, Dictionary<string, string?>>? CertificateTweak { get; set; }
    public Action? OnFirstGh { get; set; }
    /// <summary>Stands in for FileSystemChecks.ReadSetupRunIdFloor (HKLM\SOFTWARE\Albera\SetupRunIdFloor): null = no floor; it may throw the refusal for a value that is not a number.</summary>
    public Func<ulong?> ReadFloor { get; set; } = () => null;
    private bool _firstGh = true;

    public Scenario()
    {
        Directory.CreateDirectory(SetupDirectory);
        File.WriteAllBytes(Path.Combine(SetupDirectory, "gh.exe"), GhBytes);
        File.WriteAllBytes(Path.Combine(SetupDirectory, "trusted_root.jsonl"), RootBytes);
        PinnedTools.GhSha256 = FileSystemChecks.Sha256(GhBytes);
        PinnedTools.TrustedRootSha256 = FileSystemChecks.Sha256(RootBytes);
        PinnedTools.BuildRunId = 0;
        var hashes = new FileHashes();
        foreach (var component in SetupLayout.Components)
        {
            var list = hashes[component.Name] = [];
            foreach (var name in new[] { component.Executable, "runtime.dll", "sub/data.json", "Z.dll" })
                list[name] = FileSystemChecks.Sha256(Write($"{SetupLayout.RepoDirectory}/{component.PublishDirectory}/{name}", $"{component.Name}:{name}"));
        }
        TreeHash = BuildHashes.CanonicalTreeHash(hashes);
        Write(SetupLayout.BuildHashesFile, BuildHashesJson(hashes, TreeHash));
        foreach (var rel in new[] { SetupLayout.HostScript, SetupLayout.HostLibrary, SetupLayout.SetupExecutable }) Write(rel, "synthetic " + rel);
        Write($"{SetupLayout.RepoDirectory}/{SetupLayout.ControlPlaneAppHashes}", "{\"component\":\"control-plane\",\"files\":{}}\n");
        File.WriteAllBytes(Path.Combine(Update, "setup", "gh.exe"), GhBytes);
        File.WriteAllBytes(Path.Combine(Update, "setup", "trusted_root.jsonl"), RootBytes);
        WriteBundles();
    }

    public string Path_(string relative) => Path.Combine(Update, relative.Replace('/', '\\'));

    /// <summary>Writes the install record with this text (a test makes it as the installer script would, or as someone else would).</summary>
    public void WriteInstallRecord(string json)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(InstallRecordPath)!);
        File.WriteAllText(InstallRecordPath, json, new UTF8Encoding(false));
    }

    public string Write(string relative, string text)
    {
        var path = Path_(relative);
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        File.WriteAllText(path, text, new UTF8Encoding(false));
        return path;
    }

    /// <summary>(Re)writes one placeholder bundle file per attested file, named by the file's current SHA-256 like `gh attestation download` does.</summary>
    public void WriteBundles()
    {
        Directory.CreateDirectory(Path_(SetupLayout.BundlesDirectory));
        RelativeBySha.Clear();
        foreach (var rel in SetupLayout.AttestedFiles)
        {
            var sha = FileSystemChecks.Sha256(Path_(rel));
            RelativeBySha[sha] = rel;
            Write($"{SetupLayout.BundlesDirectory}/sha256-{sha}.jsonl", $"{{\"synthetic bundle for\":\"{rel}\"}}\n");
        }
    }

    public SetupDeps Deps()
    {
        Runner.Gh = FakeGh;
        return new SetupDeps
        {
            Runner = Runner,
            Folders = new KnownFolders(SetupLayout.SystemDirectory, SetupLayout.ProgramFilesDirectory, SetupLayout.ProgramDataDirectory),
            IsElevated = () => Elevated,
            SetupDirectory = SetupDirectory,
            InstalledSetupDirectory = InstalledDirectory ?? SetupDirectory,
            WorkRoot = WorkRoot,
            NewWorkName = () => "work-" + Guid.NewGuid().ToString("N"),
            CreateWorkDirectory = path => CreateWorkDirectory(path),
            AdministratorOnlyProblems = path => AdminProblems(path),
            PathHasReparsePoint = _ => false,
            InstallRecordPath = InstallRecordPath,
            ReadRunIdFloor = () => ReadFloor(),
            Out = Out,
        };
    }

    public SetupOptions Options(SetupMode mode = SetupMode.Install, EngineOptions? engine = null) =>
        new(mode, Update, NoPause: true, engine ?? new EngineOptions(null, null, null, false, null, null));

    public ProcessResult GhOk(ProcessSpec spec) => FakeGh(spec);

    private ProcessResult FakeGh(ProcessSpec spec)
    {
        if (_firstGh) { _firstGh = false; OnFirstGh?.Invoke(); }
        var file = spec.Arguments[2];
        var sha = FileSystemChecks.Sha256(file);
        var expected = GhVerifier.BuildArguments(file, spec.Arguments[4], spec.Arguments[6]);
        if (!spec.Arguments.SequenceEqual(expected) || !File.Exists(spec.Arguments[4]) || Path.GetFileName(spec.Arguments[4]) != $"sha256-{sha}.jsonl")
            throw new InvalidOperationException("gh was started with unexpected arguments: " + string.Join(" ", spec.Arguments));
        if (!RelativeBySha.TryGetValue(sha, out var rel)) return new ProcessResult(1, "", "no attestation found for this file\nsecond line", false, false);
        var entries = Attestations(rel).Select(a => Entry(sha, a, rel)).ToList();
        return new ProcessResult(0, "[" + string.Join(",", entries) + "]", "", false, false);
    }

    private string Entry(string sha, Attested attested, string rel)
    {
        var certificate = new Dictionary<string, string?>
        {
            ["subjectAlternativeName"] = SetupLayout.CertificateIdentity,
            ["issuer"] = SetupLayout.OidcIssuer,
            ["sourceRepositoryURI"] = SetupLayout.RepositoryUrl,
            ["sourceRepositoryIdentifier"] = SetupLayout.RepositoryId,
            ["sourceRepositoryOwnerIdentifier"] = SetupLayout.OwnerId,
            ["sourceRepositoryRef"] = SetupLayout.SourceRef,
            ["githubWorkflowRepository"] = SetupLayout.Repository,
            ["githubWorkflowRef"] = SetupLayout.SourceRef,
            ["buildSignerURI"] = SetupLayout.CertificateIdentity,
            ["runnerEnvironment"] = SetupLayout.HostedRunner,
            ["sourceRepositoryDigest"] = attested.Commit,
            ["buildSignerDigest"] = attested.Commit,
            ["runInvocationURI"] = $"{SetupLayout.RepositoryUrl}/actions/runs/{attested.Run}/attempts/1",
        };
        CertificateTweak?.Invoke(rel, certificate);
        return GhEntry(sha, certificate);
    }

    /// <summary>The JSON object `gh attestation verify --format json` prints for one attestation (the parts the policy reads, in the shape the gh manual describes).</summary>
    public static string GhEntry(string sha, Dictionary<string, string?> certificate, string predicate = SetupLayout.ProvenancePredicate, bool timestamps = true, string? subjectSha = null)
    {
        using var stream = new MemoryStream();
        using (var w = new Utf8JsonWriter(stream))
        {
            w.WriteStartObject();
            w.WriteStartObject("attestation"); w.WriteString("note", "synthetic"); w.WriteEndObject();
            w.WriteStartObject("verificationResult");
            w.WriteStartObject("statement");
            w.WriteString("predicateType", predicate);
            w.WriteStartArray("subject");
            w.WriteStartObject(); w.WriteString("name", "other-file.bin"); w.WriteStartObject("digest"); w.WriteString("sha256", new string('9', 64)); w.WriteEndObject(); w.WriteEndObject();
            w.WriteStartObject(); w.WriteString("name", "the-file"); w.WriteStartObject("digest"); w.WriteString("sha256", subjectSha ?? sha); w.WriteEndObject(); w.WriteEndObject();
            w.WriteEndArray();
            w.WriteStartObject("predicate"); w.WriteString("note", "attacker-controlled text is ignored"); w.WriteEndObject();
            w.WriteEndObject();
            w.WriteStartObject("signature"); w.WriteStartObject("certificate");
            foreach (var (name, value) in certificate) if (value is not null) w.WriteString(name, value);
            w.WriteEndObject(); w.WriteEndObject();
            w.WriteStartArray("verifiedTimestamps");
            if (timestamps) { w.WriteStartObject(); w.WriteString("type", "Tlog"); w.WriteEndObject(); }
            w.WriteEndArray();
            w.WriteEndObject();
            w.WriteEndObject();
        }
        return Encoding.UTF8.GetString(stream.ToArray());
    }

    public static string BuildHashesJson(FileHashes hashes, string treeHash)
    {
        using var stream = new MemoryStream();
        using (var w = new Utf8JsonWriter(stream))
        {
            w.WriteStartObject(); w.WriteNumber("version", 1); w.WriteString("treeHash", treeHash);
            w.WriteStartObject("components");
            foreach (var (name, files) in hashes)
            {
                w.WriteStartObject(name); w.WriteStartObject("files");
                foreach (var (path, sha) in files) w.WriteString(path, sha);
                w.WriteEndObject(); w.WriteEndObject();
            }
            w.WriteEndObject(); w.WriteEndObject();
        }
        return Encoding.UTF8.GetString(stream.ToArray());
    }

    public void Dispose()
    {
        try { Directory.Delete(Root, recursive: true); } catch (IOException) { /* a temp folder left behind is harmless */ }
    }
}
